function icon($name):string{$p=['grid'=>'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>','users'=>'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3a4 4 0 0 1 0 8"/><circle cx="9" cy="7" r="4"/>','calendar'=>'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 5h3m3 0h2"/>','heart'=>'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/><path d="M3 12h5l2-4 4 8 2-4h5"/>','wallet'=>'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M17 10h4v6h-4a3 3 0 0 1 0-6ZM3 5l13-3v3"/>','chart'=>'<path d="M4 3v17h17M8 16V9m5 7V5m5 11v-6"/>','settings'=>'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>','box'=>'<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 5v10l9 5 9-5V8m-9 5v10"/>','plus'=>'<path d="M12 5v14M5 12h14"/>','search'=>'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>','arrow'=>'<path d="M19 12H5m6-6-6 6 6 6"/>','logout'=>'<path d="M9 3H4v18h5m5-5 5-4-5-4m-5 4h10"/>','file'=>'<path d="M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 12h8m-8 4h6"/>','check'=>'<path d="m5 12 4 4L19 6"/>','menu'=>'<path d="M4 6h16M4 12h16M4 18h16"/>','sun'=>'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>'];return '<svg viewBox="0 0 24 24" aria-hidden="true">'.($p[$name]??$p['grid']).'</svg>';}
function head($title):void{?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#0b8b7f"><title><?=e($title)?> | <?=e(setting('name','مدیریت کلینیک مسیحا'))?></title><link rel="icon" href="/logo"><link rel="stylesheet" href="/assets/app.css?v=2"><script defer src="/assets/persian-date.js?v=2"></script><script defer src="/assets/app.js?v=2"></script><script defer src="/assets/admin.js?v=2"></script><link rel="stylesheet" href="/theme.css"><link rel="stylesheet" href="/assets/admin.css?v=2"></head><body class="<?=setting('help','1')==='1'?'':'help-off'?>"><?php }
function layout($page,$title,$subtitle=''):void{head($title);$nav=['dashboard'=>['/','نمای کلی','grid'],'appointments'=>['/appointments','نوبت‌ها و تقویم','calendar'],'patients'=>['/patients','پرونده بیماران','users'],'episodes'=>['/episodes','دوره‌های درمان','heart'],'finance'=>['/finance','امور مالی','wallet'],'reports'=>['/reports','گزارش‌ها','chart'],'staff'=>['/staff','همکاران و دسترسی‌ها','users'],'services'=>['/services','خدمات و پکیج‌ها','box'],'labels'=>['/labels','لیبل‌ها','box'],'forms'=>['/forms','فرم‌های مراجعه','file'],'resources'=>['/resources','اتاق‌ها و تجهیزات','box'],'imports'=>['/imports','انتقال از بقراط','file'],'settings'=>['/settings','تنظیمات کلینیک','settings']];?>
<a class="skip" href="#main">رفتن به محتوای اصلی</a><aside class="sidebar" id="sidebar"><a class="brand" href="/"><?php global $config;if(is_file($config['storage'].'/logo.png')):?><img src="/logo" alt="لوگوی کلینیک"><?php else:?><span class="brand-initial">م</span><?php endif;?><span><?=e(setting('name','مدیریت کلینیک مسیحا'))?><small>همراهِ مسیر بهبودی</small></span></a><span class="nav-label">فضای کاری کلینیک</span><nav aria-label="منوی اصلی"><?php foreach($nav as $k=>$n):if(!can($k))continue;?><a href="<?=$n[0]?>" <?=$k===$page?'aria-current="page"':''?>><?=icon($n[2])?><span><?=$n[1]?></span><?php if($k===$page):?><i></i><?php endif;?></a><?php endforeach;?></nav><div class="sidebar-bottom"><div class="sidebar-note"><?=icon('heart')?><strong>مراقبت، با نظم بیشتر</strong><small>هر جلسه، یک قدم به بهبودی</small></div><a class="portal-link" href="/patient/login" target="_blank">پورتال بیمار <?=icon('arrow')?></a><form method="post"><?php csrf();?><input type="hidden" name="action" value="logout"><button class="logout" type="submit"><?=icon('logout')?> خروج از حساب</button></form></div></aside>
<div class="workspace"><header class="topbar"><button class="menu-toggle" aria-label="نمایش منو" type="button" data-menu><?=icon('menu')?></button><div class="breadcrumb"><?=e(setting('name','مدیریت کلینیک مسیحا'))?> <span>/</span> <strong><?=e($title)?></strong></div><div class="top-actions"><span class="today"><?=icon('calendar')?><?=jd(date('Y-m-d'),'EEEE، d MMMM yyyy')?></span><span class="divider"></span><div class="avatar"><?=e(mb_substr(user()['name'],0,1))?></div><div class="user-meta"><strong><?=e(user()['name'])?></strong><small><?=e(['admin'=>'مدیر کلینیک','reception'=>'پذیرش','therapist'=>'درمانگر','finance'=>'امور مالی'][user()['role']])?></small></div></div></header><nav class="workspace-nav"><?php if(can('appointments')):?><a href="/appointment/new">نوبت‌دهی</a><?php endif;if(can('patients')):?><a href="/patients">تمامی مراجعین</a><?php liveSearch();endif;?></nav><main id="main" class="main"><div class="page-heading"><div><span class="eyebrow">مدیریت کلینیک فیزیوتراپی</span><h1><?=e($title)?></h1><?php if($subtitle):?><p><?=e($subtitle)?></p><?php endif;?></div><?php if(can('appointments')):?><a class="button primary" href="/appointment/new"><?=icon('plus')?> ثبت نوبت</a><?php endif;?></div><?php if(isset($_SESSION['flash'])):?><div class="notice success" role="status"><?=icon('check')?><?=e($_SESSION['flash'])?></div><?php unset($_SESSION['flash']);endif;global $error;if($error??''):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;}
function endLayout():void{?></main><footer class="footer">مسیحا <span>•</span> مدیریت ساده‌تر، مراقبت بهتر <small>نسخه مستقل ۱.۲</small></footer></div></body></html><?php }
function help($text):void{if(!$text)return;?><span class="field-help"><button type="button" aria-label="راهنمای فیلد">؟</button><span role="tooltip"><?=e($text)?></span></span><?php }
function field($name,$label,$value='',$type='text',$hint='',$required=false,$wide=false,$attrs=''):void{$value=$type==='password'?'':($_POST[$name]??$value);?><div class="field <?=$wide?'wide':''?>"><label for="<?=e($name)?>"><?=e($label)?><?php if($required):?><span class="required">*</span><?php endif;help($hint);?></label><?php if($type==='textarea'):?><textarea id="<?=e($name)?>" name="<?=e($name)?>" rows="3" <?=$required?'required':''?> <?= $attrs?>><?=e($value)?></textarea><?php else:?><input id="<?=e($name)?>" name="<?=e($name)?>" type="<?=e($type)?>" value="<?=e($value)?>" <?=$required?'required':''?> <?=$attrs?>><?php endif;?></div><?php }
function selectfield($name,$label,$options,$value='',$hint='',$required=false):void{$value=$_POST[$name]??$value;?><div class="field"><label for="<?=e($name)?>"><?=e($label)?><?php if($required):?><span class="required">*</span><?php endif;help($hint);?></label><select id="<?=e($name)?>" name="<?=e($name)?>" <?=$required?'required':''?>><?php foreach($options as $k=>$v):?><option value="<?=e($k)?>" <?=(string)$value===(string)$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div><?php }
function formstart($action,$multipart=false):void{?><form method="post" <?=$multipart?'enctype="multipart/form-data"':''?> class="edit-form"><?php csrf();?><input type="hidden" name="action" value="<?=e($action)?>"><?php }
function formend($label='ذخیره اطلاعات',$back='/'):void{?><div class="form-actions"><button class="button primary" type="submit"><?=icon('check')?><?=e($label)?></button><a class="button secondary" href="<?=e($back)?>">بازگشت</a></div></form><?php }
function emptyState($title,$description,$url='',$action=''):void{?><div class="empty-state"><span><?=icon('file')?></span><h3><?=e($title)?></h3><p><?=e($description)?></p><?php if($url):?><a class="button secondary" href="<?=e($url)?>"><?=e($action)?></a><?php endif;?></div><?php }
function sectiontitle($title,$description=''):void{?><div class="section-title"><h2><?=e($title)?></h2><?php if($description):?><p><?=e($description)?></p><?php endif;?></div><?php }
function patientName($p):string{return trim($p['fname'].' '.$p['lname']);}
function therapists():array{$rows=q("SELECT id,name FROM staff WHERE active=1 AND role IN ('admin','therapist') ORDER BY name")->fetchAll();return [''=>'انتخاب درمانگر']+array_column($rows,'name','id');}
function sessionTable($rows,$patient=true):void{if(!$rows){emptyState('نوبتی در این بازه نیست','با ثبت نوبت، برنامه جلسات اینجا نمایش داده می‌شود.','/appointment/new','ثبت اولین نوبت');return;}?><div class="table-scroll"><table><thead><tr><th>زمان مراجعه</th><?php if($patient):?><th>بیمار</th><?php endif;?><th>درمانگر و خدمت</th><th>اتاق</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($rows as $s):?><tr><td><strong><?=jd($s['starts_at'],'HH:mm')?></strong><small><?=jd($s['starts_at'])?></small></td><?php if($patient):?><td><a class="person" href="/patient?id=<?=$s['pid']?>"><span class="mini-avatar"><?=e(mb_substr($s['fname'],0,1))?></span><span><strong><?=e(patientName($s))?></strong><small>پرونده <?=fa($s['pid'])?></small></span></a></td><?php endif;?><td><strong><?=e($s['therapist_name'])?></strong><small><?=e($s['treatment']?:'جلسه فیزیوتراپی')?></small></td><td><?=e($s['room']?:'—')?><small><?=e($s['clinic_name']??'')?></small></td><td><?=badge($s['status'])?><?php if(!empty($s['label_name'])):?><small class="badge" style="color:<?=e($s['label_color'])?>"><?=e($s['label_name'])?></small><?php endif;?></td><td><?php if(scope('forms.visit')==='all'||(scope('forms.visit')==='own'&&(int)$s['created_by']===(int)user()['id'])):?><a class="icon-link" href="/session?id=<?=$s['id']?>" aria-label="جزئیات جلسه"><?=icon('arrow')?></a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php }
function sessions($where='1=1',$args=[],$limit=100):array{return q('SELECT s.*,p.pid,p.fname,p.lname,u.name therapist_name,l.name label_name,l.color label_color,c.name clinic_name FROM physio_sessions s JOIN physio_episodes ep ON ep.id=s.episode_id JOIN patients p ON p.pid=ep.pid LEFT JOIN staff u ON u.id=s.therapist_id LEFT JOIN labels l ON l.id=s.label_id LEFT JOIN clinics c ON c.id=s.clinic_id WHERE ('.$where.') AND '.patientScope('p').' ORDER BY s.starts_at LIMIT '.(int)$limit,$args)->fetchAll();}
